fibonacci-sequence.pseudocode:
def fib_memo(n, memo=None):  # 하향식 메모이제이션 O(n)
    if memo is None:
        memo = {}
    if n <= 1:
        return n
    if n not in memo:
        memo[n] = (fib_memo(n - 1, memo)
                   + fib_memo(n - 2, memo))
    return memo[n]

def fib_iter(n):  # 상향식, 두 변수만 유지 → 공간 O(1)
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def fib_pair(n):  # (F(n), F(n+1)), 행렬 거듭제곱과 동치 O(log n)
    if n == 0:
        return (0, 1)
    a, b = fib_pair(n // 2)
    c = a * (2 * b - a)  # F(2k)
    d = a * a + b * b  # F(2k+1)
    return (d, c + d) if n % 2 else (c, d)

file-carving.pseudocode:
def carve(data, header, footer, max_size):
    found, i = [], 0
    while True:
        start = data.find(header, i)  # 헤더 검색
        if start < 0:
            break
        end = data.find(footer, start + len(header))
        if end < 0 or end + len(footer) - start > max_size:
            end = start + max_size  # 푸터 없음: 최대 크기
        else:
            end += len(footer)  # 푸터 포함
        found.append(data[start:end])
        i = end  # 추출 구간 이후부터 계속
    return found

finite-difference.pseudocode:
def forward_diff(f, x, h=1e-5):
    return (f(x + h) - f(x)) / h  # 오차 O(h)

def central_diff(f, x, h=1e-5):
    return (f(x + h) - f(x - h)) / (2 * h)  # 오차 O(h²)

def second_diff(f, x, h=1e-4):  # 2계 도함수 근사
    return (f(x + h) - 2 * f(x) + f(x - h)) / h ** 2

# 예: f = sin, x = 1 → 참값 cos(1) = 0.5403023…
# h를 1e-12처럼 너무 작게 하면 반올림 오차로 부정확

finite-state-machine.pseudocode:
# DFA: '01'로 끝나는 이진 문자열 수락
DELTA = {  # 전이함수 δ(상태, 입력) → 다음 상태
    ('q0', '0'): 'q1', ('q0', '1'): 'q0',
    ('q1', '0'): 'q1', ('q1', '1'): 'q2',
    ('q2', '0'): 'q1', ('q2', '1'): 'q0',
}
START, ACCEPT = 'q0', {'q2'}

def run_dfa(s):
    state = START  # 초기 상태 q0
    for ch in s:
        if (state, ch) not in DELTA:
            return False  # 정의되지 않은 입력 → 거부
        state = DELTA[(state, ch)]
    return state in ACCEPT  # 종료(수락) 상태 여부

firewall.pseudocode:
def filter_packet(pkt, rules, sessions):
    key = (pkt.src, pkt.sport, pkt.dst, pkt.dport)
    if key in sessions:  # 상태 검사: 기존 세션
        return 'ALLOW'
    for r in rules:  # 위에서부터 첫 일치 규칙
        if r.matches(pkt):
            if r.action == 'ALLOW':
                rev = (pkt.dst, pkt.dport,
                       pkt.src, pkt.sport)
                sessions.update({key, rev})  # 응답 허용
            return r.action
    return 'DENY'  # 기본 거부(Default Deny)
